mapper.delete:
DELETE FROM category_bsr_baseline
WHERE baseline_month = #{baselineMonth}

    AND marketplace = #{marketplace}

mapper.insert:
INSERT INTO category_bsr_baseline ( marketplace, bsr_id, bsr_bucket, baseline_month, sample_size, units_p25, units_p50, units_p75, price_avg, confidence, computed_at ) WITH filtered AS ( SELECT marketplace, bsr_id, bsr, units, price FROM competitor_products WHERE month = #{baselineMonth} AND bsr_id IS NOT NULL AND bsr_id != '' AND bsr IS NOT NULL AND units IS NOT NULL
AND marketplace = #{marketplace}
), ranked AS ( SELECT marketplace, bsr_id, CASE WHEN bsr < 5000 THEN 'lt5k' WHEN bsr < 20000 THEN '5k20k' WHEN bsr < 50000 THEN '20k50k' WHEN bsr < 150000 THEN '50k150k' ELSE 'gt150k' END AS bsr_bucket, units, price, PERCENT_RANK() OVER ( PARTITION BY marketplace, bsr_id, CASE WHEN bsr < 5000 THEN 1 WHEN bsr < 20000 THEN 2 WHEN bsr < 50000 THEN 3 WHEN bsr < 150000 THEN 4 ELSE 5 END ORDER BY units ) AS units_pr FROM filtered ) SELECT marketplace, bsr_id, bsr_bucket, #{baselineMonth} AS baseline_month, COUNT(*) AS sample_size, MAX(CASE WHEN units_pr <= 0.25 THEN units END) AS units_p25, MAX(CASE WHEN units_pr <= 0.50 THEN units END) AS units_p50, MAX(CASE WHEN units_pr <= 0.75 THEN units END) AS units_p75, ROUND(AVG(price), 2) AS price_avg, CASE WHEN COUNT(*) >= 100 THEN 'high' WHEN COUNT(*) >= 30 THEN 'mid' ELSE 'low' END AS confidence, NOW() AS computed_at FROM ranked GROUP BY marketplace, bsr_id, bsr_bucket
